    private static Object finite(double v){return Double.isFinite(v)?v:JSONObject.NULL;}
    public static Object suggestionScopeJson(DetectionTuner.Report report)throws Exception {
        if(report.context.window==null)return JSONObject.NULL;JSONObject j=processingScopeJson(report.context.window);
        if(report.context.mappedInput()){PelletDetector.Result input=null;for(DetectionTuner.Trial t:report.trials)if(t.result!=null){input=t.result;break;}double[] a=report.context.inputMapping();j.put("type","original_resolution_representative_tile");j.put("roi_input",report.context.hasInputRoi());j.put("input_width",input==null?JSONObject.NULL:input.width);j.put("input_height",input==null?JSONObject.NULL:input.height);j.put("scale_x_to_preview",a[0]);j.put("scale_y_to_preview",a[1]);j.put("local_to_full_x",a[2]);j.put("local_to_full_y",a[3]);j.put("outside_roi_original_pixels_analyzed",!report.context.hasInputRoi());j.put("analyzed_pixels_per_mm_at_search",input!=null&&report.context.physical()?report.context.pixelsPerMm(input):JSONObject.NULL);}return j;
    }
    /** Cena da análise: bancada (padrão da 0.11.0) ou correia (pelotas pequenas e numerosas). */
    public static Object sceneJson(DetectionTuner.Option applied)throws Exception {
        if(applied==null)return JSONObject.NULL;PelletDetector.Parameters p=applied.parameters;JSONObject j=new JSONObject();
        j.put("mode",applied.sceneName());j.put("min_radius_fraction_of_width",p.minRadiusFraction);j.put("max_radius_fraction_of_width",p.maxRadiusFraction);j.put("max_objects",p.maxObjects);j.put("work_side_px",p.workSide(1024));
        if(applied.belt){j.put("ellipse_fit_upsampling_max",2);j.put("crack_screening","inconclusive when crop radius < 20 px; belt pellets are usually smaller, so no crack indication is expected");j.put("occlusion_note","pellets partly covered by others are fitted from their visible boundary only; the apparent size distribution may be biased and is not a sieve result");j.put("detailed_mode_available",false);}
        return j;
    }
    /** Rastreabilidade do modelo quando a localização aplicada for a rede neural. */
